/**
 * The mastery system, exported from the shipping build.
 *
 * Generated by `analysis/export_mastery_web.py` from the 9 `MasteryInfo`
 * ScriptableObjects, `DatabaseManager.MasteryNPCLevelCostPerLevel` and the game's
 * own `LocalizationJson`. Do not hand-edit: re-run the exporter.
 *
 * The original gates mastery behind the talent tree: a node granting `UnlockMastery1`
 * .. `UnlockMastery9` is what makes each tile appear (`DatabaseManager.cs:716-754`
 * maps index -> `UnlockMastery<index+1>`). The NPC's own level, paid in BatCurrency,
 * is a separate track that hands out those unlocks one at a time.
 */

export interface MasteryDef {
  index: number;
  id: string;
  /** Pinnacle masteries have no upgradeable stat: they prime the next pack. */
  isPinnacle: boolean;
  /** `PinnacleEffectType`: 0 MageScroll, 1 GoldenPack, 2 ArcherItem. */
  pinnacleEffect: number;
  maxLevel: number;
  /** `ExpressionEvaluator` input, evaluated at `level + 1` for the next price. */
  costEquation: string;
  mainStat: string | null;
  mainStatProp: string | null;
  mainValueEquation: string;
  mainSuffix: string;
  mainDecimals: number;
  awakenStat: string | null;
  awakenStatProp: string | null;
  awakenValue: number;
  awakenSuffix: string;
  awakenDecimals: number;
  awakenShowValue: boolean;
  awakenRequiredLevel: number;
  awakenCostEquation: string;
  icon: string;
  iconColor: [number, number, number, number];
  nameZh: string;
  nameEn: string;
  pinnacleDesc1Zh: string;
  pinnacleDesc2Zh: string;
}

